  // ---------- дерево душ ----------
  function treeNodes() { const o = []; for (const b of CONFIG.soulTree) b.nodes.forEach((n, i) => o.push({ ...n, branch: b, index: i })); return o; }
  const TREE = treeNodes();
  function treeDef(id) { return TREE.find(n => n.id === id); }
